	@Test
	void directAdjacencyBuildLogsMemoryLifecycle() throws Exception {
		Logger logger = (Logger) LoggerFactory.getLogger(LmdbDirectAdjacencyStore.class);
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		Level previousLevel = logger.getLevel();
		logger.setLevel(Level.INFO);
		logger.addAppender(appender);
		try {
			openPreferStore();

			List<String> messages = appender.list.stream()
					.map(ILoggingEvent::getFormattedMessage)
					.toList();
			assertThat(messages).anyMatch(message -> message.contains("Creating in-memory adjacency structures"));
			assertThat(messages).anyMatch(message -> message.contains("Published in-memory adjacency structures"));
			assertThat(messages.stream()
					.filter(message -> message.contains("in-memory adjacency structures"))
					.allMatch(message -> message.contains("memoryUsedBytes=") && message.contains("highWaterBytes=")))
							.isTrue();
		} finally {
			logger.detachAppender(appender);
			logger.setLevel(previousLevel);
			appender.stop();
		}
	}

	@Test
	void unpinnedDatasetWaitsForRevisionPublicationAfterTrackedReaderReset() throws Exception {
		openPreferStore();
		TripleStore tripleStore = backing.getTripleStore();
		TripleStore.DirectAdjacencyCommitListener delegate = direct.commitListener();
		CountDownLatch commitReachedPublicationWindow = new CountDownLatch(1);
		CountDownLatch allowRevisionPublication = new CountDownLatch(1);
		tripleStore.setDirectAdjacencyCommitHooks((delta, nextRevision) -> {
			delegate.beforeRevisionBump(delta, nextRevision);
			commitReachedPublicationWindow.countDown();
			try {
				allowRevisionPublication.await();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException("interrupted in commit publication test hook", e);
			}
		}, direct.newCommitDelta());

		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> commit = executor.submit(() -> {
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.begin();
				connection.add(S2, P2, O2);
				connection.commit();
			}
		});
		Future<org.eclipse.rdf4j.sail.base.SailDataset> dataset = null;
		try {
			assertThat(commitReachedPublicationWindow.await(5, TimeUnit.SECONDS)).isTrue();
			CountDownLatch datasetOpened = new CountDownLatch(1);
			dataset = executor.submit(() -> {
				org.eclipse.rdf4j.sail.base.SailDataset opened = backing.getExplicitSailSource()
						.dataset(IsolationLevels.NONE);
				datasetOpened.countDown();
				return opened;
			});

			assertThat(datasetOpened.await(100, TimeUnit.MILLISECONDS))
					.as("dataset acquisition must wait until the revision matching its LMDB snapshot is published")
					.isFalse();
		} finally {
			allowRevisionPublication.countDown();
			if (dataset != null) {
				dataset.get(5, TimeUnit.SECONDS).close();
			}
			commit.get(5, TimeUnit.SECONDS);
			executor.shutdownNow();
		}
	}

	private CloseableDataset dataset() {
		return new CloseableDataset(backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT));
	}

	/** Typed wrapper: the dataset class is private, but its query surface is {@link NativeLmdbQuerySource}. */
	private static final class CloseableDataset implements AutoCloseable {
		final NativeLmdbQuerySource source;
		final org.eclipse.rdf4j.sail.base.SailDataset dataset;

		CloseableDataset(org.eclipse.rdf4j.sail.base.SailDataset dataset) {
			this.dataset = dataset;
			this.source = (NativeLmdbQuerySource) dataset;
		}

		long idOf(org.eclipse.rdf4j.model.Value value) {
			return source.idOf(value);
		}

		List<long[]> rows(long subj, long pred, long obj, long context) throws IOException {
			return collect(source.statements(subj, pred, obj, context));
		}

		List<long[]> rows(StatementOrder order, long subj, long pred, long obj, long context) throws IOException {
			return collect(source.statements(order, subj, pred, obj, context));
		}

		private static List<long[]> collect(RecordIterator it) {
			List<long[]> rows = new ArrayList<>();
			try {
				long[] quad;
				while ((quad = it.next()) != null) {
					rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
							quad[TripleIndex.OBJ_IDX], Math.max(0, quad[TripleIndex.CONTEXT_IDX]) });
				}
			} finally {
				it.close();
			}
			return rows;
		}

		@Override
		public void close() {
			dataset.close();
		}
	}

	private static final Comparator<long[]> ROW_ORDER = (a, b) -> {
		for (int i = 0; i < 4; i++) {
			int cmp = Long.compareUnsigned(a[i], b[i]);
			if (cmp != 0) {
				return cmp;
			}
		}
		return 0;
	};

	private static List<long[]> sorted(List<long[]> rows) {
		List<long[]> copy = new ArrayList<>(rows);
		copy.sort(ROW_ORDER);
		return copy;
	}

	private static void assertSameRows(List<long[]> actual, List<long[]> expected) {
		assertThat(sorted(actual)).usingElementComparator(ROW_ORDER).containsExactlyElementsOf(sorted(expected));
	}

	private List<String> queryRows(String query) {
		try (RepositoryConnection connection = repo.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			List<String> rows = new ArrayList<>();
			while (result.hasNext()) {
				var row = result.next();
				rows.add(row.getValue("patient").stringValue() + "=" + row.getValue("medCount").stringValue());
			}
			rows.sort(String::compareTo);
			return rows;
		}
	}

