	@Test
	void orderedShapesUseCompatibleFastPathOrUniversalCandidate() throws IOException {
		openPreferStore();
		try (var dataset = dataset()) {
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			List<long[]> byObject = dataset.rows(StatementOrder.O, s1, p1, -1, -1);
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
			assertThat(byObject).hasSize(2);
			assertThat(Long.compareUnsigned(byObject.get(0)[2], byObject.get(1)[2])).isNegative();

			long incompatibleBefore = direct.snapshotMetrics().fallbacks(FallbackReason.INDEX_ORDER_INCOMPATIBLE);
			long universalBefore = direct.snapshotMetrics().lookupHits;
			assertSameRows(dataset.rows(StatementOrder.S, s1, p1, -1, -1), List.of(
					new long[] { s1, p1, o1, 0 },
					new long[] { s1, p1, o2, g1 }));
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.INDEX_ORDER_INCOMPATIBLE))
					.isEqualTo(incompatibleBefore);
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(universalBefore);

			long subjectOrderIncoming = direct.snapshotMetrics().lookupHits;
			List<long[]> bySubject = dataset.rows(StatementOrder.S, -1, p1, o1, -1);
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(subjectOrderIncoming);
			assertThat(bySubject).hasSize(2);
			assertThat(Long.compareUnsigned(bySubject.get(0)[0], bySubject.get(1)[0])).isNegative();
		}
	}

	@Test
	void flaggedCleanWriteTransactionServesDirectLookup() throws IOException {
		System.setProperty(LmdbDirectAdjacencyStore.CLEAN_TXN_READS_PROPERTY, "true");
		assertCleanWriteTransactionServesDirectLookup();
	}

	@Test
	void cleanWriteTransactionServesDirectLookupByDefault() throws IOException {
		assertCleanWriteTransactionServesDirectLookup();
	}

	private void assertCleanWriteTransactionServesDirectLookup() throws IOException {
		openPreferStore();
		backing.enableMultiThreading = false;
		SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED);
		try {
			sink.approve(S1, P1, O1, null);
			assertThat(direct.storeTxnStartedFlag()).isTrue();

			long hitsBefore = direct.snapshotMetrics().lookupHits;
			long bypassBefore = direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES);
			try (var dataset = dataset()) {
				assertSameRows(dataset.rows(s1, p1, -1, -1), List.of(
						new long[] { s1, p1, o1, 0 },
						new long[] { s1, p1, o2, g1 }));
			}
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES))
					.isEqualTo(bypassBefore);
		} finally {
			sink.flush();
			sink.close();
		}
	}

	@Test
	void flaggedDirtyWriteTransactionFallsBackAndReadsItsOwnAddAndRemove() throws IOException {
		System.setProperty(LmdbDirectAdjacencyStore.CLEAN_TXN_READS_PROPERTY, "true");
		openPreferStore();
		backing.enableMultiThreading = false;
		IRI uncommitted = F.createIRI("http://example.org/uncommitted");
		SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED);
		try {
			sink.approve(S1, P1, uncommitted, null);
			sink.deprecate(F.createStatement(S1, P1, O1));
			assertThat(direct.storeTxnStartedFlag()).isTrue();
			assertThat(direct.storeTxnDirtyFlag()).isTrue();

			TripleStore tripleStore = backing.getTripleStore();
			var writerTxn = tripleStore.getTxnManager().createTxn(tripleStore.writeTxn);
			List<long[]> writerRows = CloseableDataset
					.collect(tripleStore.getTriples(writerTxn, s1, p1, -1, -1, true));
			assertThat(writerRows).hasSize(2);
			assertThat(writerRows.stream().anyMatch(row -> row[2] == o1)).isFalse();
			assertThat(writerRows.stream().anyMatch(row -> row[2] == o2)).isTrue();

			long hitsBefore = direct.snapshotMetrics().lookupHits;
			long bypassBefore = direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES);
			try (var dataset = dataset()) {
				assertSameRows(dataset.rows(s1, p1, -1, -1), List.of(
						new long[] { s1, p1, o1, 0 },
						new long[] { s1, p1, o2, g1 }));
			}
			assertThat(direct.snapshotMetrics().lookupHits).isEqualTo(hitsBefore);
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES))
					.isGreaterThan(bypassBefore);
		} finally {
			backing.rollback();
			sink.close();
		}
	}

	@Test
	void flaggedRollbackResetsDirtyStateAndSameConnectionServesAgain() throws IOException {
		System.setProperty(LmdbDirectAdjacencyStore.CLEAN_TXN_READS_PROPERTY, "true");
		openPreferStore();
		backing.enableMultiThreading = false;
		IRI rolledBack = F.createIRI("http://example.org/rolled-back");
		SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED);
		try {
			sink.approve(S1, P1, rolledBack, null);
			assertThat(direct.storeTxnDirtyFlag()).isTrue();
			backing.rollback();
			assertThat(direct.storeTxnStartedFlag()).isFalse();
			assertThat(direct.storeTxnDirtyFlag()).isFalse();

			sink.approve(S1, P1, O1, null);
			assertThat(direct.storeTxnStartedFlag()).isTrue();
			assertThat(direct.storeTxnDirtyFlag()).isFalse();
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			try (var dataset = dataset()) {
				assertThat(dataset.source.has(s1, p1, o1, -1)).isTrue();
			}
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
			backing.rollback();
		} finally {
			if (direct.storeTxnStartedFlag().get()) {
				backing.rollback();
			}
			sink.close();
		}
	}

	@Test
	void disabledCleanTransactionReadsRestoresConservativeBypass() throws IOException {
		System.setProperty(LmdbDirectAdjacencyStore.CLEAN_TXN_READS_PROPERTY, "false");
		openPreferStore();
		try (var dataset = dataset()) {
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			long bypassBefore = direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES);
			direct.storeTxnStartedFlag().set(true);
			try {
				assertSameRows(dataset.rows(s1, p1, -1, -1), List.of(
						new long[] { s1, p1, o1, 0 },
						new long[] { s1, p1, o2, g1 }));
			} finally {
				direct.storeTxnStartedFlag().set(false);
			}
			assertThat(direct.snapshotMetrics().lookupHits).isEqualTo(hitsBefore);
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.READ_YOUR_WRITES))
					.isGreaterThan(bypassBefore);
		}
	}

	@Test
	void serializableIsolationBypassesDirectAdjacency() throws IOException {
		openPreferStore();
		long hitsBefore = direct.snapshotMetrics().lookupHits;
		var dataset = backing.getExplicitSailSource().dataset(IsolationLevels.SERIALIZABLE);
		try {
			List<long[]> rows = CloseableDataset.collect(
					((NativeLmdbQuerySource) dataset).statements(s1, p1, -1, -1));
			assertThat(rows).hasSize(2);
		} finally {
			dataset.close();
		}
		assertThat(direct.snapshotMetrics().lookupHits).isEqualTo(hitsBefore);
	}

	@Test
	void snapshotAfterCommitFallsBackUntilRebuildAndOldSnapshotKeepsServing() throws IOException {
		openPreferStore();
		try (var pinnedBeforeCommit = dataset()) {
			try (RepositoryConnection conn = repo.getConnection()) {
				conn.add(S2, P2, O2);
			}
			// the old pinned snapshot equals the base revision: it must keep serving exactly (invariant I3)
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			assertSameRows(pinnedBeforeCommit.rows(s1, p1, -1, -1), List.of(
					new long[] { s1, p1, o1, 0 },
					new long[] { s1, p1, o2, g1 }));
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
		}
		// a rebuild at the new revision serves new snapshots again
		assertThat(direct.buildNowForTest()).isTrue();
		long hitsBefore = direct.snapshotMetrics().lookupHits;
		try (var dataset = dataset()) {
			assertSameRows(dataset.rows(s2, p2, -1, -1), List.of(new long[] { s2, p2, o2, 0 }));
		}
		assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);
	}

	@Test
	void selectedCoverageServesSelectedAndFallsBackForUnselected() throws IOException {
		openStore(DirectAdjacencyMode.PREFER, DirectAdjacencyCoverage.SELECTED, List.of(P1));
		try (var dataset = dataset()) {
			long hitsBefore = direct.snapshotMetrics().lookupHits;
			assertSameRows(dataset.rows(s1, p1, -1, -1), List.of(
					new long[] { s1, p1, o1, 0 },
					new long[] { s1, p1, o2, g1 }));
			assertThat(direct.snapshotMetrics().lookupHits).isGreaterThan(hitsBefore);

			long uncoveredBefore = direct.snapshotMetrics().fallbacks(FallbackReason.PLANE_NOT_COVERED);
			assertSameRows(dataset.rows(s1, p2, -1, -1), List.of(new long[] { s1, p2, o1, 0 }));
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.PLANE_NOT_COVERED))
					.isGreaterThan(uncoveredBefore);

			// SELECTED cannot answer ?predicate completely: falls back before the first result
			long enumBefore = direct.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE);
			assertThat(dataset.rows(s1, -1, -1, -1)).hasSize(4);
			assertThat(direct.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE))
					.isGreaterThan(enumBefore);
		}
	}

	@Test
	void shadowComparesButNeverServes() throws IOException {
		System.setProperty(LmdbDirectAdjacencyOptions.SHADOW_SAMPLE_EVERY_PROPERTY, "1");
		openStore(DirectAdjacencyMode.SHADOW, null, null);
		try (var dataset = dataset()) {
			long comparisonsBefore = direct.snapshotMetrics().shadowComparisons;
			assertSameRows(dataset.rows(s1, p1, -1, -1), List.of(
					new long[] { s1, p1, o1, 0 },
					new long[] { s1, p1, o2, g1 }));
			LmdbAdjacencyMetrics.Snapshot metrics = direct.snapshotMetrics();
			assertThat(metrics.shadowComparisons).isGreaterThan(comparisonsBefore);
			assertThat(metrics.shadowMismatches).isZero();
			assertThat(metrics.lookupHits).isZero();
		}
	}
